local WarDogTrainer = {}
local PRODUCTS = {
    guard_dog = { name = "Pasji čuvaj", dogPupCost = 1, meatCost = 1, time = 3, cost = 30, attack = 8, defense = 6, description = "Pasji čuvaj za varovanje." },
    attack_dog = { name = "Napadni pes", dogPupCost = 1, meatCost = 2, time = 4, cost = 60, attack = 14, defense = 8, prestige = 2, description = "Napadni pes za boj." },
    mastiff = { name = "Mastif", dogPupCost = 1, meatCost = 2, time = 6, cost = 140, attack = 20, defense = 14, prestige = 5, happiness = 1, description = "Mastif za težko zaščito." },
    silver_armored_dog = { name = "Srebrno oklepni pes", dogPupCost = 1, silverCost = 1, meatCost = 2, time = 9, cost = 320, attack = 28, defense = 20, prestige = 10, happiness = 2, description = "Srebrno oklepni pes za plemiče." },
    silver_collar_war_dog = { name = "Srebrno ovratnični bojni pes", dogPupCost = 1, silverCost = 1, meatCost = 2, time = 12, cost = 680, attack = 38, defense = 28, prestige = 18, happiness = 4, description = "Bojni pes s srebrno ovratnico za visoke plemiče." },
    royal_grand_war_dog = { name = "Kraljevski veliki bojni pes", dogPupCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, meatCost = 3, time = 17, cost = 1900, attack = 55, defense = 40, prestige = 45, happiness = 10, description = "Veliki kraljevski bojni pes z zlatom in dragulji za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Pasja vojaška postaja", cost = { gold = 280, wood = 130, stone = 250 }, upkeep = 7, qualityBonus = 5 },
    war_kennel = { name = "Vojaški pasjak", cost = { gold = 950, wood = 250, stone = 400, meat = 10 }, upkeep = 23, qualityBonus = 18 },
    battle_training_yard = { name = "Bojni dresurni dvori", cost = { gold = 2400, wood = 350, stone = 600, silver = 25, iron = 8 }, upkeep = 60, qualityBonus = 30 },
    royal_wardog_atelier = { name = "Kraljevski atelje bojnih psov", cost = { gold = 9500, wood = 600, stone = 1000, gold = 60, jewel = 20 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 40 },
}
WarDogTrainer.dogPupStock = 22; WarDogTrainer.meatStock = 24; WarDogTrainer.silverStock = 8; WarDogTrainer.goldStock = 6; WarDogTrainer.jewelStock = 6
WarDogTrainer.productStock = {}; WarDogTrainer.buildings = {}; WarDogTrainer.maker = nil; WarDogTrainer.activeMaking = {}; WarDogTrainer.totalProducts = 0; WarDogTrainer.dayTimer = 0
function WarDogTrainer.init() WarDogTrainer.dogPupStock=22; WarDogTrainer.meatStock=24; WarDogTrainer.silverStock=8; WarDogTrainer.goldStock=6; WarDogTrainer.jewelStock=6; WarDogTrainer.productStock={}; WarDogTrainer.buildings={}; WarDogTrainer.maker=nil; WarDogTrainer.activeMaking={}; WarDogTrainer.totalProducts=0; WarDogTrainer.dayTimer=0; print("[WarDogTrainer] Royal War Dog Trainer System initialized (6 products, 4 buildings)") end
function WarDogTrainer.hireMaker(n,s) s=s or math.random(50,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WarDogTrainer.maker={name=n or ("Dreser psov "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dreser psov najet: %s (spretnost: %d)",WarDogTrainer.maker.name,s),"success") end; return true end
function WarDogTrainer.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WarDogTrainer.build(id) local ok,e=WarDogTrainer.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WarDogTrainer.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WarDogTrainer.getQualityBonus() local b=0; for _,bd in ipairs(WarDogTrainer.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WarDogTrainer.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.dogPupCost and WarDogTrainer.dogPupStock<(d.dogPupCost or 0) then return false,"Premalo psičkov" end; if d.meatCost and WarDogTrainer.meatStock<(d.meatCost or 0) then return false,"Premalo mesa" end; if d.silverCost and WarDogTrainer.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WarDogTrainer.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WarDogTrainer.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #WarDogTrainer.buildings==0 then return false,"Potrebna delavnica" end; if not WarDogTrainer.maker then return false,"Potreben dreser psov" end; return true end
function WarDogTrainer.make(pt,qty) qty=qty or 1; local ok,e=WarDogTrainer.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.dogPupCost then WarDogTrainer.dogPupStock=WarDogTrainer.dogPupStock-d.dogPupCost*qty end; if d.meatCost then WarDogTrainer.meatStock=WarDogTrainer.meatStock-d.meatCost*qty end; if d.silverCost then WarDogTrainer.silverStock=WarDogTrainer.silverStock-d.silverCost*qty end; if d.goldCost then WarDogTrainer.goldStock=WarDogTrainer.goldStock-d.goldCost*qty end; if d.jewelCost then WarDogTrainer.jewelStock=WarDogTrainer.jewelStock-d.jewelCost*qty end; local t=d.time; if WarDogTrainer.maker then t=math.max(1,t-math.floor(WarDogTrainer.maker.skill/12)) end; table.insert(WarDogTrainer.activeMaking,{id="wardog_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,attack=d.attack or 0,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WarDogTrainer.completeMaking(m) local q=1.0+(WarDogTrainer.getQualityBonus()/100); if WarDogTrainer.maker then q=q+(WarDogTrainer.maker.skill/150) end; q=math.min(2.5,q); WarDogTrainer.productStock[m.productType]=(WarDogTrainer.productStock[m.productType] or 0)+m.quantity; WarDogTrainer.totalProducts=WarDogTrainer.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WarDogTrainer.maker then WarDogTrainer.maker.itemsMade=WarDogTrainer.maker.itemsMade+m.quantity; if math.random()<0.25 then WarDogTrainer.maker.skill=math.min(100,WarDogTrainer.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Bojni pes izurjen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"wardog.completed",{productName=m.productName,attack=m.attack,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function WarDogTrainer.update(dt) if not _G.state then return end; WarDogTrainer.dayTimer=WarDogTrainer.dayTimer+dt; if WarDogTrainer.dayTimer>=30 then WarDogTrainer.dayTimer=0; for i=#WarDogTrainer.activeMaking,1,-1 do local m=WarDogTrainer.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WarDogTrainer.completeMaking(m); table.remove(WarDogTrainer.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WarDogTrainer.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WarDogTrainer.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WarDogTrainer.getStats() return {dogPupStock=WarDogTrainer.dogPupStock,meatStock=WarDogTrainer.meatStock,silverStock=WarDogTrainer.silverStock,goldStock=WarDogTrainer.goldStock,jewelStock=WarDogTrainer.jewelStock,productStock=WarDogTrainer.productStock,numBuildings=#WarDogTrainer.buildings,hasMaker=WarDogTrainer.maker~=nil,makerName=WarDogTrainer.maker and WarDogTrainer.maker.name or "—",makerSkill=WarDogTrainer.maker and WarDogTrainer.maker.skill or 0,activeMaking=#WarDogTrainer.activeMaking,totalProducts=WarDogTrainer.totalProducts} end
return WarDogTrainer
